package ffdd.opsconsole.device.application;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import ffdd.opsconsole.device.mapper.SupportDeviceReadMapper;
import java.util.*;
import java.util.stream.LongStream;
import org.apache.ibatis.session.Configuration;
import org.junit.jupiter.api.Test;

class SupportDeviceFundReadTest {
    final SupportDeviceReadMapper mapper=mock(SupportDeviceReadMapper.class);
    final SupportDeviceReadService service=new SupportDeviceReadService(mapper);
    void empty(){when(mapper.fundReceipts(anyList())).thenReturn(List.of());when(mapper.fundTasks(anyList())).thenReturn(List.of());when(mapper.fundLedgers(anyList())).thenReturn(List.of());when(mapper.fundEvents(anyList())).thenReturn(List.of());}
    @Test void allFourBatchesPreserveBadRowsAndUseTheSameAuthorizedScope(){empty();var bad=new HashMap<String,Object>();bad.put("customerId",7L);bad.put("deleted",1);bad.put("status","FAILED");when(mapper.fundReceipts(List.of(7L,8L))).thenReturn(List.of(bad));var sources=service.readFundEarnings(List.of(8L,7L,7L));assertThat(sources.receipts()).containsExactly(bad);verify(mapper).fundReceipts(List.of(7L,8L));verify(mapper).fundTasks(List.of(7L,8L));verify(mapper).fundLedgers(List.of(7L,8L));verify(mapper).fundEvents(List.of(7L,8L));assertThatThrownBy(()->sources.receipts().get(0).put("deleted",0)).isInstanceOf(UnsupportedOperationException.class);}
    @Test void emptyScopeDoesNotQueryAndFailedQueryNeverBecomesEmpty(){assertThat(service.readFundEarnings(List.of()).receipts()).isEmpty();verifyNoInteractions(mapper);empty();when(mapper.fundTasks(List.of(7L))).thenReturn(null);assertThatThrownBy(()->service.readFundEarnings(List.of(7L))).isInstanceOf(IllegalStateException.class);when(mapper.fundTasks(List.of(7L))).thenThrow(new IllegalStateException("SQL failure"));assertThatThrownBy(()->service.readFundEarnings(List.of(7L))).hasMessage("SQL failure");}
    @Test void exactRootClosureLimitIsAcceptedAndForeignRowsFailTheWholeBatch(){empty();service.readFundEarnings(LongStream.rangeClosed(1,4096).boxed().toList());assertThatThrownBy(()->service.readFundEarnings(LongStream.rangeClosed(1,4097).boxed().toList())).isInstanceOf(IllegalArgumentException.class);when(mapper.fundEvents(List.of(7L))).thenReturn(List.of(Map.of("customerId",8L,"deleted",1)));assertThatThrownBy(()->service.readFundEarnings(List.of(7L))).isInstanceOf(IllegalStateException.class);}
    @Test void owningBoundSqlKeepsBadOriginalsAndUsesRealDdlAliases(){var config=new Configuration();config.addMapper(SupportDeviceReadMapper.class);for(String method:List.of("fundReceipts","fundTasks","fundLedgers","fundEvents")){String sql=config.getMappedStatement(SupportDeviceReadMapper.class.getName()+"."+method).getBoundSql(Map.of("scope",List.of(7L,8L))).getSql();assertThat(sql).contains("? , ?");assertThat(sql).doesNotContain("is_deleted=0","source_environment='PRODUCTION'");assertThat(sql.toUpperCase()).doesNotContain("LIMIT","FOR UPDATE");}var tasks=config.getMappedStatement(SupportDeviceReadMapper.class.getName()+".fundTasks").getBoundSql(Map.of("scope",List.of(7L))).getSql();assertThat(tasks).contains("task_config_id taskId","task_type taskType").doesNotContain("t.task_id");var wallet=config.getMappedStatement(SupportDeviceReadMapper.class.getName()+".fundWallets").getBoundSql(Map.of("customer",7L)).getSql();assertThat(wallet).contains("fund_revision revision","version","fund_incarnation incarnation");var metadata=config.getMappedStatement(SupportDeviceReadMapper.class.getName()+".fundTimePrecisions").getBoundSql(Map.of()).getSql();assertThat(metadata).contains("DATABASE()","DATETIME_PRECISION","completed_at","proof_consumed_at","wallet_posted_at");}
    @Test void precisionIsRealAndMissingDuplicateWrongOrFractionalCannotBeInvented(){when(mapper.fundTimePrecisions()).thenReturn(List.of(Map.of("tableName","nx_compute_receipt","columnName","completed_at","precision",6)));assertThat(service.timePrecisions()).containsEntry("nx_compute_receipt.completed_at",6);when(mapper.fundTimePrecisions()).thenReturn(List.of());assertThat(service.timePrecisions()).isEmpty();var r=Map.<String,Object>of("tableName","nx_compute_receipt","columnName","completed_at","precision",6);when(mapper.fundTimePrecisions()).thenReturn(List.of(r,r));assertThatThrownBy(service::timePrecisions).isInstanceOf(IllegalStateException.class);when(mapper.fundTimePrecisions()).thenReturn(List.of(Map.of("tableName","foreign","columnName","completed_at","precision",6)));assertThatThrownBy(service::timePrecisions).isInstanceOf(IllegalStateException.class);}
}
